wire VCC;
wire GND;
  \~psram_top.PSRAM_Memory_Interface_HS_Top  u_psram_top (
    .memory_clk(memory_clk),
    .rst_n(rst_n),
    .pll_lock(pll_lock),
    .cmd(cmd),
    .cmd_en(cmd_en),
